EbmlElement* findNextEbmlElement(IOCallback &DataStream, const EbmlSemanticContext &Context, int &UpperLevel, uint64 MaxDataSize, bool AllowDummyElt, unsigned int MaxLowerLevel) {
    uint64 bytesRead = 0;
    uint64 dataSize = 0;
    unsigned char idByte;

    // Try to read the next byte for an EBML ID
    while (DataStream.read(&idByte, 1, bytesRead) && bytesRead < MaxDataSize) {
        if (idByte == 0) continue; // Skip zero bytes

        // Determine the element's ID and size
        EbmlId elementId = static_cast<EbmlId>(idByte);
        uint64 elementSize = 0;
        uint64 sizeBytesRead = 0;

        if (!readEbmlSize(DataStream, elementSize, sizeBytesRead, MaxDataSize - bytesRead)) {
            return nullptr; // Error while reading size
        }

        bytesRead += sizeBytesRead;

        // Check if the element fits within the allowed data size
        if (bytesRead + elementSize > MaxDataSize) {
            return nullptr; // Element exceeds size limit
        }

        // Create a new EBML element based on the context
        EbmlElement* newElement = Context.create(elementId);
        if (!newElement) {
            return nullptr; // Failed to create the element
        }

        // Set element size and validate hierarchy
        newElement->SetSize(elementSize);
        int elementLevel = UpperLevel + 1;
        if (elementLevel > static_cast<int>(MaxLowerLevel)) {
            delete newElement;
            return nullptr; // Element level exceeds max allowed
        }

        // Handle dummy elements if allowed
        if (!AllowDummyElt && newElement->IsDummy()) {
            delete newElement;
            continue;
        }

        // Successfully found and validated element
        UpperLevel = elementLevel;
        return newElement;
    }

    return nullptr; // No valid element found
}

EbmlElement* FindNextEbmlElement(IOCallback &DataStream, const EbmlSemanticContext &Context, int &UpperLevel, uint64 MaxDataSize, bool AllowDummyElt, unsigned int MaxLowerLevel) {
    EbmlElement *element = NULL;
    uint64 currentPos = DataStream.Tell();
    uint64 remainingSize = MaxDataSize;

    if (currentPos >= MaxDataSize)
        return NULL;

    // Read potential ID
    EBML_ID id;
    size_t bytesRead = DataStream.Read(&id, sizeof(EBML_ID));

    if (bytesRead != sizeof(EBML_ID))
        return NULL;

    currentPos = DataStream.Tell();
    remainingSize = MaxDataSize - currentPos;

    if (remainingSize <= 0)
        return NULL;

    // Determine the size of the element
    uint64 elementSize = 0;
    if (!ReadEbmlSize(DataStream, elementSize, remainingSize))
        return NULL;

    // Check for maximum data size constraint
    if (currentPos + elementSize > MaxDataSize)
        return NULL;

    // Validate and create EBML element
    element = ebmlCreateElement(Context, id, elementSize, UpperLevel, AllowDummyElt, MaxLowerLevel);
    if (!element)
        return NULL;

    return element;
}

EbmlElement* FindNextEbmlElement(IOCallback &DataStream, const EbmlSemanticContext &Context, int &UpperLevel, uint64 MaxDataSize, bool AllowDummyElt, unsigned int MaxLowerLevel) {
    // Determine the current position in the data stream
    int64 CurrentPos = DataStream.Tell();
    if (CurrentPos < 0) {
        return nullptr; // Failed to determine position
    }

    if (DataStream.Eof()) {
        return nullptr; // End of stream reached without finding an element
    }

    // Read the potential element ID from the data stream
    uint32 ElementID;
    int64 IdReadSize = DataStream.Read(&ElementID, sizeof(ElementID));
    if (IdReadSize != sizeof(ElementID)) {
        return nullptr; // Incomplete ID read
    }

    // Read the size of the element
    uint64 ElementSize;
    int64 SizeReadSize = ReadEbmlSize(DataStream, ElementSize);
    if (SizeReadSize < 0) {
        return nullptr; // Failed to read the size
    }

    // Calculate the total bytes consumed by the ID and size
    int64 TotalConsumedSize = IdReadSize + SizeReadSize;

    // Calculate the total data size required for this element
    uint64 ElementTotalSize = ElementSize + TotalConsumedSize;
    if (ElementTotalSize > MaxDataSize) {
        return nullptr; // Element exceeds maximum size limit
    }

    // Determine the level of the element based on its ID using the context
    int ElementLevel = Context.GetLevel(ElementID);
    if (ElementLevel <= 0) {
        return nullptr; // Invalid or unknown element level
    }

    // Check if the element level is within the allowed bounds
    if (ElementLevel > MaxLowerLevel || (UpperLevel >= ElementLevel)) {
        return nullptr; // Element level is out of bounds
    }

    // Handle dummy elements if allowed
    if (AllowDummyElt && Context.IsDummyElement(ElementID)) {
        // Skip the element
        if (!DataStream.Seek(ElementSize, SEEK_CUR)) {
            return nullptr; // Failed to skip the dummy element
        }

        return nullptr;
    }

    // Create and return the EBML element
    EbmlElement* Element = new EbmlElement(ElementID, ElementSize, ElementLevel, CurrentPos);
    return Element;
}

EbmlElement* FindNextEbmlElement(IOCallback &DataStream, const EbmlSemanticContext &Context, int &UpperLevel, uint64 MaxDataSize, bool AllowDummyElt, unsigned int MaxLowerLevel) {
    uint64 CurrentPos = DataStream.Tell();
    uint64 RemainingSize = MaxDataSize;

    if (RemainingSize <= 0 || (CurrentPos + RemainingSize) > DataStream.GetSize())
        return NULL;

    unsigned char ID = 0;
    size_t IDSize = 1;
    if (!DataStream.Read(&ID, IDSize))
        return NULL;

    // Determine the size of the EBML element
    uint64 ElementSize = 0;
    size_t SizeSize = 0;
    if (!EbmlReadSize(DataStream, ElementSize, SizeSize))
        return NULL;

    if (ElementSize + IDSize > RemainingSize)
        return NULL;

    // Check if the size would exceed the data stream's capacity
    if (CurrentPos + IDSize + SizeSize + ElementSize > DataStream.GetSize())
        return NULL;

    // Check for dummy element handling if allowed
    if (AllowDummyElt && (ID == 0x00 || ElementSize == 0))
        return NULL;

    // Create the EBML element based on the ID and context
    EbmlElement* Element = EbmlCreateElementFromId(ID, Context);
    if (!Element)
        return NULL;

    // Set the element's size
    Element->SetSize(ElementSize);

    // Ensure the lower level does not exceed the maximum allowed
    if (Element->GetLevel() > MaxLowerLevel)
        return NULL;

    // Update the upper level reference
    UpperLevel = Element->GetLevel();

    return Element;
}

EbmlElement* findNextEbmlElement(IOCallback &DataStream, const EbmlSemanticContext &Context, int &UpperLevel, uint64 MaxDataSize, bool AllowDummyElt, unsigned int MaxLowerLevel) {
    uint64 currentPos = DataStream.tellg();
    uint64 dataSize = 0;
    uint8 idByte;

    // Read potential ID bytes
    while (DataStream.read(reinterpret_cast<char*>(&idByte), sizeof(idByte))) {
        uint64 id = idByte;

        // Skip if ID is zero (invalid in EBML)
        if (id == 0) {
            continue;
        }

        // Read the size of the element
        uint64 size = 0;
        int sizeBytes = 0;
        uint8 sizeByte;
        do {
            if (!DataStream.read(reinterpret_cast<char*>(&sizeByte), sizeof(sizeByte))) {
                return nullptr; // Incomplete size data
            }
            size = (size << 7) | (sizeByte & 0x7F);
            sizeBytes++;
        } while ((sizeByte & 0x80) != 0);

        // Calculate the total size of the element
        dataSize = sizeBytes + size;

        // Check if the element fits within the allowed data size
        if (currentPos + dataSize > MaxDataSize) {
            return nullptr; // Exceeds max data size
        }

        // Validate the level of the element based on the context
        int elementLevel = Context.getLevel(id);
        if (elementLevel > MaxLowerLevel) {
            return nullptr; // Element is at too high a level
        }

        // Create the EBML element
        EbmlElement* element = new EbmlElement(id, dataSize);
        if (element == nullptr) {
            return nullptr; // Memory allocation failed
        }

        // If dummy element is not allowed and this is a dummy, skip
        if (!AllowDummyElt && Context.isDummyElement(id)) {
            delete element;
            return nullptr;
        }

        // Update the current upper level
        UpperLevel = elementLevel;

        return element;
    }

    return nullptr; // No more data or elements found
}
